function is_the_mileage_group( mileage, mileage_group ) {
  var mileage_10k_multiplier = 0;
  var group_multiplier = Math.floor( mileage_group / 10000 );

  while ( mileage > 10000 ) {
	mileage_10k_multiplier++;

	mileage -= 10000;
  }

  return mileage_10k_multiplier == group_multiplier;
}

function display_bid_warning(message)
{
  $('#bid-input-wrapper').css('background', 'red');
  $('#bid-input-wrapper').css('color', 'white');
  $('#bid-input-wrapper').css('padding', '10px');
  $('#bid-input-wrapper').css('margin-bottom', '10px');
  $('#bid-input-wrapper').css('border-radius', '5px');
  $('#warning-text').empty().html(message);
  $('#bid-trigger').attr('disabled', true);
}

function hide_bid_warning()
{
  $('#bid-input-wrapper').css('background', 'transparent');
  $('#bid-input-wrapper').css('color', 'black');
  $('#bid-input-wrapper').css('padding', '0');
  $('#bid-input-wrapper').css('margin-bottom', '0');
  $('#bid-input-wrapper').css('border-radius', '0');
  $('#warning-text').empty();
  $('#bid-trigger').attr('disabled', false);
}

