function is_the_mileage_group( mileage, mileage_group ) {
  var mileage_10k_multiplier = 0;
  var group_multiplier = Math.floor( mileage_group / 10000 );

  while ( mileage > 10000 ) {
	mileage_10k_multiplier++;

	mileage -= 10000;
  }

  return mileage_10k_multiplier == group_multiplier;
}

